<include file="Public:header"/><style type="text/css">.importexcel{height: 60px;line-height: 60px;}.importexcel a{ cursor: pointer;}</style>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('Employee/store')}">店铺列表</a>|                    <a href="{pigcms{:U('Employee/check_store')}">审核店铺列表</a>|                    <a href="{pigcms{:U('Employee/check_refuse_store')}">审核拒绝店铺列表</a>|                    <a href="{pigcms{:U('Employee/store_import')}" class="on">店铺信息导入</a>|                    <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/store_add')}','添加店铺',620,440,true,false,false,addbtn,'store_add',true);">添加店铺</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<div class="importexcel">							&nbsp;&nbsp;&nbsp;示例表格：							<a target="_blank" href="{pigcms{$config['site_url']}/static/file/employee_sample.xls">点击下载</a>					</td>				</tr>				<tr>					<td>						<div class="importexcel">						  <span>Excel导入： </span>						  <a href="javascript:;"><input type="file" title="Excel导入"  id="excelimport"  name="excelfile" value="选择文件上传"/></a>						</div>					</td>				</tr>                <tr>                    <td class="err_info" style="display: none; color: red;">                    </td>                </tr>			</table>		</div><script type="text/javascript" src="{pigcms{$static_public}js/ajaxfileupload.js"></script><script type='text/javascript'>// 上传excel 表格function ExcelImport(){       $.ajaxFileUpload({       url:"{pigcms{:U('Employee/excel_import')}",    //需要链接到服务器地址       secureuri:false,       fileElementId:'excelimport',                 //文件选择框的id属性       dataType: 'json',       success: function (data) {           if(data.error){                alert(data.msg);           }else{                alert('导入成功！');                console.log('excel_import_data',data.import_error);                window.location.href="{pigcms{:U('Employee/store')}";           }           console.log('data---', data);           console.log('import_error---', data.import_error);           if (data.import_error) {               var import_error = data.import_error;               var len = import_error.length;               var str = '';               $('.err_info').css('display', 'block');               for (var i=0;i<len;i++) {                   var key = i+1;                   str = '<div> 错误行数'+key+': '+import_error[i]['msg']+'</div>';                   $('.err_info').append(str);               }           }		   $("#excelimport").change(function(){                 ExcelImport();                       });        }      });   }  $("#excelimport").change(function(){       ExcelImport(); });</script><include file="Public:footer"/>